const nextQueuedIndexJob = `-- name: NextQueuedIndexJob :one
SELECT id, tenant_id, config_version, status, total, done, failed, started_at, finished_at, error, source, upload_key, index_version, created_at FROM index_jobs WHERE status = 'queued' ORDER BY created_at, id LIMIT 1 FOR UPDATE SKIP LOCKED
`

func (q *Queries) NextQueuedIndexJob(ctx context.Context) (IndexJob, error) {
	row := q.db.QueryRowContext(ctx, nextQueuedIndexJob)
	var i IndexJob
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.ConfigVersion,
		&i.Status,
		&i.Total,
		&i.Done,
		&i.Failed,
		&i.StartedAt,
		&i.FinishedAt,
		&i.Error,
		&i.Source,
		&i.UploadKey,
		&i.IndexVersion,
		&i.CreatedAt,
	)
	return i, err
}

