const upsertPlan = `-- name: UpsertPlan :exec
INSERT INTO plans (id, name, max_total_ms, search_rps, search_burst, events_rps, byo_allowed, egress_allowlist, max_custom_fields, max_page_depth)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON DUPLICATE KEY UPDATE name = VALUES(name), max_total_ms = VALUES(max_total_ms), search_rps = VALUES(search_rps),
  search_burst = VALUES(search_burst), events_rps = VALUES(events_rps), byo_allowed = VALUES(byo_allowed),
  egress_allowlist = VALUES(egress_allowlist), max_custom_fields = VALUES(max_custom_fields), max_page_depth = VALUES(max_page_depth)
`

type UpsertPlanParams struct {
	ID              string          `json:"id"`
	Name            string          `json:"name"`
	MaxTotalMs      int32           `json:"max_total_ms"`
	SearchRps       int32           `json:"search_rps"`
	SearchBurst     int32           `json:"search_burst"`
	EventsRps       int32           `json:"events_rps"`
	ByoAllowed      bool            `json:"byo_allowed"`
	EgressAllowlist json.RawMessage `json:"egress_allowlist"`
	MaxCustomFields int32           `json:"max_custom_fields"`
	MaxPageDepth    int32           `json:"max_page_depth"`
}

func (q *Queries) UpsertPlan(ctx context.Context, arg UpsertPlanParams) error {
	_, err := q.db.ExecContext(ctx, upsertPlan,
		arg.ID,
		arg.Name,
		arg.MaxTotalMs,
		arg.SearchRps,
		arg.SearchBurst,
		arg.EventsRps,
		arg.ByoAllowed,
		arg.EgressAllowlist,
		arg.MaxCustomFields,
		arg.MaxPageDepth,
	)
	return err
}

